import { google } from "googleapis";
import { NextResponse } from "next/server";

export async function GET(request) {
    try {
        console.log("=== INICIANDO GET /api/deudores ===");

        // Verificar variables de entorno
        if (!process.env.GOOGLE_SHEET_ID || !process.env.GOOGLE_CLIENT_EMAIL || !process.env.GOOGLE_PRIVATE_KEY) {
            console.error("❌ Faltan variables de entorno");
            return NextResponse.json(
                { error: "Configuración incompleta" },
                { status: 500 }
            );
        }

        let privateKey = process.env.GOOGLE_PRIVATE_KEY;
        if (privateKey.startsWith('"')) {
            privateKey = JSON.parse(privateKey);
        }
        privateKey = privateKey.replace(/\\n/g, "\n");

        const auth = new google.auth.GoogleAuth({
            credentials: {
                client_email: process.env.GOOGLE_CLIENT_EMAIL,
                private_key: privateKey,
            },
            scopes: ["https://www.googleapis.com/auth/spreadsheets"],
        });

        const sheets = google.sheets({ version: "v4", auth });
        const spreadsheetId = process.env.GOOGLE_SHEET_ID;

        console.log("📊 Leyendo hoja de impuestos...");

        // Leer todos los impuestos
        const responseImpuestos = await sheets.spreadsheets.values.get({
            spreadsheetId: spreadsheetId,
            range: "impuestos!A2:E",
        });

        console.log("📊 Leyendo hoja de usuarios...");

        // Leer usuarios
        const responseUsuarios = await sheets.spreadsheets.values.get({
            spreadsheetId: spreadsheetId,
            range: "usuarios!A2:C",
        });

        const impuestos = responseImpuestos.data.values || [];
        const usuarios = responseUsuarios.data.values || [];

        console.log(`Impuestos encontrados: ${impuestos.length}`);
        console.log(`Usuarios encontrados: ${usuarios.length}`);

        // Meses en orden
        const meses = [
            "Enero",
            "Febrero",
            "Marzo",
            "Abril",
            "Mayo",
            "Junio",
            "Julio",
            "Agosto",
            "Septiembre",
            "Octubre",
            "Noviembre",
            "Diciembre",
        ];

        const mesActual = new Date().getMonth(); // 0-11
        console.log(`Mes actual: ${meses[mesActual]} (índice ${mesActual})`);

        // Tipos de impuestos
        const tiposImpuestos = [
            "ABL",
            "ABLUC",
            "ARBA",
            "AYSA",
            "AYSAUC",
            "EDESUR",
            "EXPENSAS",
            "METROGAS",
            "MUNICIPAL",
            "TELECOM",
        ];

        // Departamentos únicos (sin Admin)
        const departamentosUnicos = [
            ...new Set(
                usuarios
                    .map((u) => u[0])
                    .filter((d) => d && d !== "Admin")
            ),
        ];

        console.log(`Departamentos a analizar: ${departamentosUnicos.length}`);

        // Objeto para almacenar deudas por departamento
        const deudoresPorDepartamento = {};

        departamentosUnicos.forEach((depto) => {
            const emailFicticio =
                depto.toLowerCase().replace(/\s+/g, "") + "@example.com";

            deudoresPorDepartamento[depto] = {
                departamento: depto,
                email: emailFicticio,
                deudas: [],
            };

            // Por cada mes PASADO (no el actual)
            for (let mesIndex = 0; mesIndex < mesActual; mesIndex++) {
                const nombreMes = meses[mesIndex];

                // Por cada tipo de impuesto
                tiposImpuestos.forEach((tipoImpuesto) => {
                    // Buscar si existe ese impuesto pagado
                    const impuestoPagado = impuestos.find(
                        (imp) =>
                            imp[0] === depto &&
                            imp[1] === tipoImpuesto &&
                            imp[2] === nombreMes
                    );

                    // Si NO existe, es una deuda
                    if (!impuestoPagado) {
                        deudoresPorDepartamento[depto].deudas.push({
                            mes: nombreMes,
                            impuesto: tipoImpuesto,
                        });
                    }
                });
            }
        });

        // Filtrar solo los que tienen deudas
        const deudores = Object.values(deudoresPorDepartamento).filter(
            (d) => d.deudas.length > 0
        );

        console.log(`Departamentos con deudas: ${deudores.length}`);

        // Calcular estadísticas
        const totalDeudas = deudores.reduce((sum, d) => sum + d.deudas.length, 0);
        const totalDepartamentosDeudores = deudores.length;

        const resultado = {
            deudores,
            estadisticas: {
                totalDeudas,
                totalDepartamentosDeudores,
                mesActual: meses[mesActual],
            },
        };

        console.log("✅ Respuesta generada correctamente");
        console.log(`Total deudas: ${totalDeudas}`);

        return NextResponse.json(resultado);
    } catch (error) {
        console.error("❌ Error en /api/deudores:", error);
        return NextResponse.json(
            { error: `Error al obtener deudores: ${error.message}` },
            { status: 500 }
        );
    }
}